/* Constants */
export const defaultSettings = {"audioDevice":"auto","audioQuality":"high","autoplay":true,"checkForUpdates":true,"closeToTray":false,"includePrereleases":false,"pauseWatchHistory":false,"searchHistory":"youtube","skipDisliked":false,"stableVolume":"off","statsForNerds":false} as const;

/* Types */
/**
 *  The codec a file holds, the local half of `AudioCodec` in `@ymusic/core`.
 *  Stored in SQLite by its serde name.
 */
export type AudioCodec = "opus" | "aac" | "mp3" | "flac" | "alac" | "vorbis" | "pcm" | "unknown";

/**  An output mpv can play through. `name` is what `audio-device` takes. */
export type AudioDevice = {
	name: string,
	description: string,
};

export type AudioQuality = "high" | "normal" | "low";

/**
 *  Stats for nerds, for the song playing. Each is None when mpv or the meters
 *  have nothing to say yet.
 */
export type AudioStats = {
	codec: string | null,
	sampleRate: number | null,
	channels: string | null,
	/**  Bits per second, as mpv estimates it from the stream. */
	bitrate: number | null,
	/**  How far YouTube measured the track above its reference level. */
	youtubeLoudnessDb: number | null,
	/**  Stable volume's gain; None when it leaves the track alone. */
	gainDb: number | null,
	/**  The ReplayGain tag mpv applies to a local file with stable volume on. */
	replaygainDb: number | null,
	/**  Loudness over the song so far, in LUFS: its average level. */
	integratedLufs: number | null,
	/**  Loudness over the last 400 ms. */
	momentaryLufs: number | null,
	/**  The track's loudest true peak so far, before the gain, in dBTP. */
	peakDb: number | null,
	/**
	 *  The loudest true peak after the gain and limiter. None under
	 *  ReplayGain, which no meter sees.
	 */
	outputPeakDb: number | null,
	/**  How far the limiter pulled peaks down; None when there is no limiter. */
	limiterDb: number | null,
};

/**
 *  A browser profile with a cookie store. The id is what the frontend sends
 *  back to import it; the path behind it never leaves Rust.
 */
export type Browser = {
	id: string,
	name: string,
};

/**
 *  Mirrors `Thumbnail` in `@ymusic/core`. Cover art is extracted to the cache
 *  directory during a scan; the frontend converts `path` with Tauri's
 *  `convertFileSrc` because a bare `file://` will not load in the webview.
 */
export type CoverArt = {
	path: string,
	width: number,
	height: number,
};

/**
 *  Which package this build was produced as. The Linux updater needs it: a
 *  `.deb` install updates through `pkexec dpkg -i`, while a hand-run binary or
 *  a future Flatpak must be told to update through its own channel instead of
 *  being handed a package it cannot install.
 * 
 *  Set at build time via `YMUSIC_INSTALL_FLAVOR`; `Unknown` is the honest default
 *  for a `cargo run`.
 */
export type InstallFlavor = "deb" | "windows-installer" | "unknown";

export type LoadRequest = {
	/**
	 *  The track this stream belongs to, echoed back on `ended` and `error` so
	 *  the queue knows which track the event is about.
	 */
	trackId: string,
	url: string,
	/**
	 *  Replayed verbatim onto mpv's request. Includes the user agent, cookies,
	 *  and any PO token that the resolving fetch used.
	 */
	headers?: { [key in string]: string },
	startPaused?: boolean,
	/**  YouTube's loudness for the track, in dB above its reference level. */
	loudnessDb?: number | null,
	/**  Where to start, for a queue restored at launch. From the top when None. */
	startMs?: number | null,
};

/**  Mirrors `StreamLease` in `@ymusic/core`. */
export type LocalLease = {
	trackId: string,
	url: string,
	itag: number | null,
	codec: AudioCodec,
	bitrate: number | null,
	isPremiumFormat: boolean,
	loudnessDb: number | null,
	headers: { [key in string]: string },
	expiresAt: number | null,
	playerClient: string | null,
	degraded: string | null,
};

/**  Mirrors `Track` in `@ymusic/core`, in its local-file flavour. */
export type LocalTrack = {
	/**  Namespaced as `local:<hash>` so it can share a queue with `yt:` ids. */
	id: string,
	path: string,
	title: string,
	artist: string,
	album: string | null,
	albumArtist: string | null,
	trackNumber: number | null,
	discNumber: number | null,
	year: number | null,
	durationMs: number | null,
	codec: AudioCodec,
	bitrate: number | null,
	coverArt: CoverArt | null,
	/**  When the file was first scanned, in seconds since the Unix epoch. */
	addedAt: number,
};

/**  A media key or widget action, as the frontend handles it. */
export type MediaKeyEvent = { type: "play" } | { type: "pause" } | { type: "toggle" } | { type: "next" } | { type: "previous" } | { type: "stop" } | { type: "seekBy"; offsetMs: number } | { type: "setPosition"; positionMs: number } | 
/**  A slider position in 0..=1, the same unit the player's volume takes. */
{ type: "setVolume"; volume: number };

/**  What the frontend knows about the current track. */
export type MediaTrack = {
	title: string,
	artist: string,
	album: string | null,
	/**  A remote image, for YouTube tracks. */
	coverUrl: string | null,
	/**
	 *  A file on disk, for local tracks. Kept separate from `cover_url`
	 *  because each OS wants a file spelled differently; see `file_cover_url`.
	 */
	coverPath: string | null,
	durationMs: number | null,
};

/**
 *  What the app knows about where it is running. The frontend shows some of it
 *  on the about screen; the updater decides what it may do with the rest.
 */
export type PlatformSummary = {
	os: string,
	arch: string,
	appVersion: string,
	installFlavor: InstallFlavor,
	supportsInAppUpdate: boolean,
	/**  False without a system tray library, so the page can't offer the tray. */
	hasTray: boolean,
};

export type PlaybackEvent = { type: "status"; status: PlaybackStatus } | { type: "position"; positionMs: number; durationMs: number | null } | { type: "ended"; trackId: string | null } | 
/**  mpv went on to the appended track by itself, with no gap. */
{ type: "advanced"; trackId: string } | { type: "error"; trackId: string | null; message: string };

export type PlaybackStatus = "idle" | "loading" | "playing" | "paused" | "ended";

/**  The reply to the page asking where playback is. */
export type Position = {
	positionMs: number,
	durationMs: number | null,
};

/**
 *  The frontend's queue, which Rust stores as it comes and never reads. The
 *  frontend parses it on the way back (`packages/ipc/src/queue.ts`).
 */
export type QueueJson = unknown;

export type QueuePosition = {
	trackId: string,
	positionMs: number,
};

/**  Both files, as read at launch. */
export type SavedQueue = {
	queue: unknown | null,
	position: QueuePosition | null,
};

export type SavedVolume = {
	volume: number,
	/**  The last settled volume above zero. */
	unmuted: number,
};

export type ScanFailure = {
	path: string,
	reason: string,
};

export type ScanReport = {
	added: number,
	updated: number,
	/**  Skipped because the file has not changed since the last scan. */
	unchanged: number,
	/**
	 *  Files that looked like audio but could not be read. Reported rather
	 *  than thrown away so a corrupt file is visible instead of silently
	 *  missing from the library.
	 */
	failed: ScanFailure[],
	removed: number,
};

/**  Where searches are remembered. */
export type SearchHistory = 
/**  On the account, as YouTube Music records them. */
"youtube" | 
/**  In a list on this device, with searches kept off the account. */
"device" | 
/**  Nowhere. */
"off";

export type Settings = {
	/**  When the queue runs out, its suggestions play on. */
	autoplay: boolean,
	audioQuality: AudioQuality,
	stableVolume: StableVolume,
	/**  An mpv `audio-device` name. `auto` follows the system's default output. */
	audioDevice: string,
	skipDisliked: boolean,
	pauseWatchHistory: boolean,
	searchHistory: SearchHistory,
	/**  Closing the window hides it to the tray and playback carries on. */
	closeToTray: boolean,
	checkForUpdates: boolean,
	includePrereleases: boolean,
	/**  Loudness, peaks and the stable volume gain, measured as a song plays. */
	statsForNerds: boolean,
};

/**
 *  The settings `settings_set` changes: each field present replaces the
 *  saved one, and the rest stay. One field per setting, so the frontend's type
 *  for a patch comes from here too.
 */
export type SettingsPatch = {
	autoplay?: boolean | null,
	audioQuality?: AudioQuality | null,
	stableVolume?: StableVolume | null,
	audioDevice?: string | null,
	skipDisliked?: boolean | null,
	pauseWatchHistory?: boolean | null,
	searchHistory?: SearchHistory | null,
	closeToTray?: boolean | null,
	checkForUpdates?: boolean | null,
	includePrereleases?: boolean | null,
	statsForNerds?: boolean | null,
};

/**  How stable volume evens songs out. */
export type StableVolume = "off" | 
/**  Loud songs turned down and quiet ones turned up. */
"on" | 
/**  Loud songs turned down, quiet ones left alone. */
"loudOnly";

/**  A release newer than the running build. */
export type Update = {
	version: string,
	url: string,
	prerelease: boolean,
};

